  51	\begin{definition}[Two-player one-round games]\label{def:game}
  52		\lean{MIPStarRE.QPBT.Game}
  53		\leanok
  54		A \emph{two-player one-round game} $\mathfrak G$ is specified by a tuple $(\mathcal X, \mathcal Y, \mathcal A, \mathcal B, \mu, D)$ where
  55		\begin{enumerate}
  56			\item $\mathcal X$ and $\mathcal Y$ are finite sets, called the \emph{question alphabets},
  57			\item $\mathcal A$ and $\mathcal B$ are finite sets, called the \emph{answer alphabets},
  58			\item $\mu$ is a probability distribution over $\mathcal X \times \mathcal Y$, called the \emph{question distribution}, and
  59			\item $D \colon \mathcal X \times \mathcal Y \times \mathcal A \times \mathcal B \to \{0,1\}$ is a function, called the \emph{decision predicate}.
  60		\end{enumerate}
  61	\end{definition}
  62	
  63	\begin{definition}[Tensor product strategies]\label{def:tensor-product-strategy}
  64		\lean{MIPStarRE.QPBT.Strategy}
  65		\leanok
  66		\uses{def:game, def:povm-conventions}
  67		A \emph{tensor product strategy} $\mathcal S$ for a game $\mathfrak G = (\mathcal X, \mathcal Y, \mathcal A, \mathcal B, \mu, D)$ is a tuple $(\ket{\psi}, A, B)$ where
  68		\begin{itemize}
  69			\item $\ket{\psi}$ is a pure quantum state, i.e.\ a unit vector in $\mathcal H_A \ot \mathcal H_B$ for finite-dimensional complex Hilbert spaces $\mathcal H_A$, $\mathcal H_B$,
  70			\item $A$ is a set $\{A^x\}$ such that for every $x \in \mathcal X$, $A^x = \{A^x_a\}_{a \in \mathcal A}$ is a POVM on $\mathcal H_A$, and
  71			\item $B$ is a set $\{B^y\}$ such that for every $y \in \mathcal Y$, $B^y = \{B^y_b\}_{b \in \mathcal B}$ is a POVM on $\mathcal H_B$.
  72		\end{itemize}
  73	\end{definition}
  74	
  75	\begin{definition}[Tensor product value]\label{def:tensor-product-value}
  76		\lean{MIPStarRE.QPBT.Strategy.value, MIPStarRE.QPBT.Game.value}
  77		\leanok
  78		\uses{def:tensor-product-strategy}
  79		The \emph{tensor product value} of a tensor product strategy $\mathcal S = (\ket{\psi}, A, B)$ with respect to a game $\mathfrak G = (\mathcal X, \mathcal Y, \mathcal A, \mathcal B, \mu, D)$ is
  80		\[
  81			\operatorname{val}^*(\mathfrak G, \mathcal S) = \sum_{x,\,y,\,a,\,b} \mu(x,y)\, D(x,y,a,b)\, \bra{\psi} A^x_a \ot B^y_b \ket{\psi}\,.
  82		\]
  83		For $v \in [0,1]$ we say that the strategy $\mathcal S$ \emph{passes (or wins) $\mathfrak G$ with probability $v$} if $\operatorname{val}^*(\mathfrak G, \mathcal S) \ge v$. The \emph{tensor product value} of $\mathfrak G$ is
  84		\[
  85			\operatorname{val}^*(\mathfrak G) = \sup_{\mathcal S} \operatorname{val}^*(\mathfrak G, \mathcal S)\,,
  86		\]
  87		where the supremum is taken over all tensor product strategies $\mathcal S$ for $\mathfrak G$.
  88	\end{definition}
  89	
  90	Unless specified otherwise, all strategies considered in what follows are tensor product strategies, and we simply call them \emph{strategies}; similarly, we refer to $\operatorname{val}^*(\mathfrak G)$ as the \emph{value} of the game $\mathfrak G$.
  91	
  92	% The source labels this definition def:projective-strategy. That label is already carried
  93	% by the low individual degree test track (Chapter 2), where it names the strategy format
  94	% specific to that test, so a distinct label is used here; see the following remark.
  95	\begin{definition}[Projective strategies]\label{def:projective-strategy-general}
