 106	\begin{definition}[Symmetric games and symmetric strategies]\label{def:symmetric-game}
 107		\lean{MIPStarRE.QPBT.SymmetricGame, MIPStarRE.QPBT.SymmetricGame.toGame, MIPStarRE.QPBT.SymmetricStrategy, MIPStarRE.QPBT.SymmetricStrategy.toStrategy}
