 171	\begin{lemma}[The printed attainment claim, recorded and refuted]
 172		\label{lem:symmetric-strat-printed-claim}
 173		\lean{MIPStarRE.QPBT.PrintedSymmetricProjectiveAttainmentClaim}
 174		\lean{MIPStarRE.QPBT.not_forall_printedSymmetricProjectiveAttainmentClaim}
 175		\leanok
