 201	\begin{definition}[Commuting strategies]\label{def:comm-strategy}
 202		\lean{MIPStarRE.QPBT.IsCommutingOn, MIPStarRE.QPBT.Strategy.IsCommuting}
 203		\leanok
 204		\uses{def:game, def:tensor-product-strategy}
 205		Let $\mathfrak G = (\mathcal X, \mathcal Y, \mathcal A, \mathcal B, \mu, D)$ be a game, and let $\mathcal S = (\ket{\psi}, A, B)$ be a strategy for $\mathfrak G$ such that $\mathcal H_A = \mathcal H_B$. We say that $\mathcal S$ is a \emph{commuting strategy for $\mathfrak G$} if for all question pairs $(x,y)$ in the support of $\mu$ (i.e.\ all $(x,y)$ with $\mu(x,y) > 0$) we have
 206		\[
 207			[A^x_a, B^y_b] = 0 \qquad \text{for all } a \in \mathcal A,\ b \in \mathcal B\,,
 208		\]
 209		where $[A,B] = AB - BA$ denotes the commutator.
 210	\end{definition}
