 212	\begin{definition}[Consistent measurements]\label{def:consistent-measurement}
 213		\lean{MIPStarRE.QPBT.Measurement.IsConsistentOn}
 214		\leanok
 215		\uses{def:povm-conventions}
 216		Let $\mathcal A$ be a finite set, let $\ket{\psi} \in \mathcal H \ot \mathcal H$ be a state, and let $\{M_a\}_{a \in \mathcal A}$ be a projective measurement on $\mathcal H$. We say that \emph{$\{M_a\}_{a \in \mathcal A}$ is consistent on $\ket{\psi}$} if and only if
 217		\[
 218			\forall a \in \mathcal A\,, \qquad M_a \ot \Id_B\, \ket{\psi} = \Id_A \ot M_a\, \ket{\psi}\,.
 219		\]
 220		When the state $\ket{\psi}$ is clear from context we simply say that $\{M_a\}_{a \in \mathcal A}$ is consistent.
 221	\end{definition}
 222	
 223	The terminology arises from the fact that when the measurement $\{M_a\}$ is performed on both registers of $\ket{\psi}$, the probability of obtaining twice the same outcome is
 224	\[
 225		\sum_a \bra{\psi} M_a \ot M_a \ket{\psi} = \sum_a \bra{\psi} \Id_A \ot (M_a)^2 \ket{\psi} = \sum_a \bra{\psi} \Id_A \ot M_a \ket{\psi} = 1\,,
 226	\]
 227	where the first equality is by the definition of consistency, the second uses that $\{M_a\}$ is projective, and the last uses $\sum_a M_a = \Id$.
 228	
 229	\begin{definition}[Consistent strategies]\label{def:consistent-strategy}
 230		\lean{MIPStarRE.QPBT.IsConsistentStrategyOn, MIPStarRE.QPBT.SymmetricStrategy.IsConsistent}
 231		\leanok
 232		\uses{def:consistent-measurement, def:projective-strategy-general}
 233		Let $\mathcal S = (\ket{\psi}, A, B)$ be a projective strategy with state $\ket{\psi} \in \mathcal H \ot \mathcal H$, for some Hilbert space $\mathcal H$, defined on question alphabets $\mathcal X$ and $\mathcal Y$ and answer alphabets $\mathcal A$ and $\mathcal B$, respectively. We say that $\mathcal S$ is \emph{consistent} if for all $x \in \mathcal X$ the measurement $\{A^x_a\}_{a \in \mathcal A}$ is consistent on $\ket{\psi}$, and for all $y \in \mathcal Y$ the measurement $\{B^y_b\}_{b \in \mathcal B}$ is consistent on $\ket{\psi}$.
 234	\end{definition}
 235	
 236	We almost always restrict attention to symmetric strategies; in this case consistency implies that whenever both players are sent the same question, they provide the same answer.
