 288	\begin{definition}[Distance between strategies]\label{def:strategy-distance}
 289		\lean{MIPStarRE.QPBT.AreCloseStrategies}
 290		\leanok
 291		\uses{def:tensor-product-strategy, def:state-distance, def:povm-distance}
 292		Let $\mathfrak G = (\mathcal X, \mathcal Y, \mathcal A, \mathcal B, \mu, D)$ be a nonlocal game and let $\mathcal S = (\psi, A, B)$ and $\mathcal S' = (\psi', A', B')$ be strategies for $\mathfrak G$. For $\delta \in [0,1]$ we say that \emph{$\mathcal S$ is $\delta$-close to $\mathcal S'$} if the following conditions hold.
 293		\begin{enumerate}
 294			\item The states $\ket{\psi}, \ket{\psi'}$ are states in the same Hilbert space $\mathcal H_A \ot \mathcal H_B$ and are $\delta$-close.
 295			\item For all $x \in \mathcal X$ and $y \in \mathcal Y$, we have $A^x_a \approx_\delta (A')^x_a$ and $B^y_b \approx_\delta (B')^y_b$, with the approximations holding under the distribution $\mu$ (i.e.\ under its corresponding marginals), on either $\ket{\psi}$ or $\ket{\psi'}$.
 296		\end{enumerate}
 297	\end{definition}
