1529		The win predicate $D^{\mathrm{pauli}} = D^{\mathrm{pauli}}_{\mathsf{qldparams}}$ is the function of the tuple $(t_{\mathrm A}, x_{\mathrm A}, t_{\mathrm B}, x_{\mathrm B}, a_{\mathrm A}, a_{\mathrm B})$ determined by the following clauses, evaluated for $w \in \{\mathrm A, \mathrm B\}$ and $W \in \{X,Z\}$; in all cases where no action is indicated, the predicate accepts. In the last four clauses, the content of the player whose type lies in $\mathcal T^{\mathrm{ms}} \cup \{\mathsf{Pair}, (\mathsf{Pair},X), (\mathsf{Pair},Z)\}$ is a tuple $(u_X, u_Z, r_X, r_Z)$, from which the predicate first computes
1530		\begin{equation}
1531			\label{eq:gamma-value}
1532			\gamma = \tr\bigl( (\mathrm{ind}_m(u_X) \cdot r_X) \cdot (\mathrm{ind}_m(u_Z) \cdot r_Z) \bigr) \in \F_2\;,
1533		\end{equation}
1534		where $\mathrm{ind}_m(\cdot) \in \F_q^M$ is the indicator vector of the low-degree encoding (Chapter~\ref{chap:qpbt-algebra}), the inner dot denotes the dot product on $\F_q^M$, and $\tr\colon \F_q \to \F_2$ is the finite-field trace.
1535		\begin{enumerate}
1536			\item (\textbf{Consistency check}) If $t_{\mathrm A} = t_{\mathrm B}$, accept if and only if $a_{\mathrm A} = a_{\mathrm B}$.
1537			\item (\textbf{Low-degree check}) Let $\mathsf{ldparams} = (q,m,d,1)$; admissibility of $\mathsf{qldparams}$ gives $d \ge 1$ and $m \mid q$, so this is a parameter tuple as in Definition~\ref{def:ld-game}.
1538			\begin{enumerate}
1539				\item If $t_w = (\mathsf{Point},W)$ and $t_{\overline w} = (\mathsf{ALine},W)$, accept if $D^{\mathrm{ld}}_{\mathsf{ldparams}}$ accepts $(\mathsf{Point}, x_w, \mathsf{ALine}, x_{\overline w}, a_w, a_{\overline w})$.
1540				\item If $t_w = (\mathsf{Point},W)$ and $t_{\overline w} = (\mathsf{DLine},W)$, accept if $D^{\mathrm{ld}}_{\mathsf{ldparams}}$ accepts $(\mathsf{Point}, x_w, \mathsf{DLine}, x_{\overline w}, a_w, a_{\overline w})$.
1541			\end{enumerate}
1542			\item (\textbf{Consistency check}) If $t_w = (\mathsf{Point},W)$ and $t_{\overline w} = (\mathsf{Pauli},W)$, accept if $g_{a_{\overline w}}(x_w) = a_w$, where $g_{a_{\overline w}}$ is the low-degree encoding of $a_{\overline w} \in \F_q^M$ (Chapter~\ref{chap:qpbt-algebra}).
1543			\item (\textbf{Commutation check}) If $t_w = (\mathsf{Pair},W)$ and $t_{\overline w} = \mathsf{Pair}$, accept if $a_w = \beta_W$ or $\gamma \neq 0$.
1544			\item (\textbf{Consistency check}) If $t_w = (\mathsf{Point},W)$ and $t_{\overline w} = (\mathsf{Pair},W)$, accept if $\tr(a_w r_W) = a_{\overline w}$ or $\gamma \neq 0$.
1545			\item (\textbf{Magic Square check}) If $t_w = \mathsf{Constraint}_i$ and $t_{\overline w} = \mathsf{Variable}_j$, accept if $\gamma = 0$, or if $a_w$ satisfies the equation of $\mathsf{Constraint}_i$ and $\alpha_j = a_{\overline w}$.
1546			\item (\textbf{Consistency check}) If $t_w = (\mathsf{Point},W)$ and $t_{\overline w} = \mathsf{Variable}_j$, accept if $\gamma = 0$, or if $j = 1$, $W = X$, and $\tr(a_w r_X) = a_{\overline w}$, or if $j = 5$, $W = Z$, and $\tr(a_w r_Z) = a_{\overline w}$.
1547		\end{enumerate}
1548		The game $\mathfrak{G}^{\mathrm{Pauli}}_{\mathsf{qldparams}}$ is the typed game with type set $\mathcal T^{\mathrm{pauli}}$, the question distribution of Definition~\ref{def:pauli-question-distribution}, and win predicate $D^{\mathrm{pauli}}_{\mathsf{qldparams}}$.
1549	\end{definition}
1550	
1551	Note the one-sided gating on $\gamma$: the commutation check and the $\mathsf{Pair}$ consistency check accept automatically when $\gamma \neq 0$, while the Magic Square check and the $\mathsf{Variable}$ consistency check accept automatically when $\gamma = 0$.
